/**
 * Returns the current optimization options.
 * @returns {OptimizationOptions}
 */
export function getOptimization(): OptimizationOptions;
/**
 * Updates optimization options. Missing fields keep their previous values.
 * @param {Partial<OptimizationOptions>} next
 * @returns {OptimizationOptions}
 */
export function setOptimization(next?: Partial<OptimizationOptions>): OptimizationOptions;
export type OptimizationOptions = {
    /**
     * - When true, helper utilities like
     * `uniformPlus` will try to convert uniform values into const nodes to reduce
     * uniform bandwidth.
     */
    uniformToConst?: boolean;
};
